// Relational Database Engine Simulation inside n8n static data
const staticData = $getWorkflowStaticData('global');

// 1. DDL: Create Tables & Seed Master Data
staticData.tables = staticData.tables || {};
staticData.tables.customers = [
  { customerId: "CUST-101", name: "Apex Global", balance: 5000.00, creditLimit: 10000.00 },
  { customerId: "CUST-001", name: "Acme Corp", balance: 1200.00, creditLimit: 5000.00 },
  { customerId: "CUST-002", name: "Globex Inc", balance: 450.00, creditLimit: 500.00 }
];
staticData.customers = staticData.tables.customers;
staticData.orders = staticData.orders || [];
staticData.orderItems = staticData.orderItems || [];
staticData.tables.orders = staticData.orders;
staticData.tables.order_items = staticData.orderItems;

return {
  json: {
    status: "DATABASE_INITIALIZED",
    schema: {
      tables: ["customers", "orders", "order_items"],
      constraints: ["FK_order_items_orders", "CHECK_credit_limit"],
      indexes: ["idx_orders_customer", "idx_items_order"]
    },
    timestamp: new Date().toISOString()
  }
};

return [
  {
    json: {
      orderId: "ORD-DB-5001",
      customerId: "CUST-101",
      orderDate: new Date().toISOString(),
      lineItems: [
        { sku: "SKU-SRV-01", description: "Cloud Managed Server", quantity: 2, unitPrice: 450.00 },
        { sku: "SKU-LIC-02", description: "Enterprise Security Seat", quantity: 5, unitPrice: 75.00 }
      ]
    }
  }
];

const staticData = $getWorkflowStaticData('global');
staticData.orders = staticData.orders || [];
const order = $input.item.json;
const totalAmount = (order.lineItems || []).reduce((acc, it) => acc + (it.quantity * it.unitPrice), 0);
const orderRecord = {
  orderId: order.orderId,
  customerId: order.customerId,
  orderDate: order.orderDate,
  totalAmount: totalAmount,
  status: "PENDING"
};
staticData.orders.push(orderRecord);
return {
  json: {
    ...order,
    headerInserted: true,
    totalAmount: totalAmount
  }
};

const staticData = $getWorkflowStaticData('global');
staticData.orderItems = staticData.orderItems || [];
const order = $input.item.json;
const lineItems = order.lineItems || [];
const insertedItems = lineItems.map((it, idx) => {
  const record = {
    itemId: `ITEM-${order.orderId}-${idx + 1}`,
    orderId: order.orderId,
    sku: it.sku,
    description: it.description,
    quantity: it.quantity,
    unitPrice: it.unitPrice,
    lineTotal: Number((it.quantity * it.unitPrice).toFixed(2))
  };
  staticData.orderItems.push(record);
  return record;
});
return {
  json: {
    orderId: order.orderId,
    customerId: order.customerId,
    totalAmount: order.totalAmount,
    itemsCount: insertedItems.length,
    items: insertedItems
  }
};

const staticData = $getWorkflowStaticData('global');
staticData.customers = staticData.customers || [
  { customerId: "CUST-101", name: "Apex Global", balance: 5000.00, creditLimit: 10000.00 }
];
const order = $input.item.json;
const customer = staticData.customers.find(c => c.customerId === order.customerId);

if (!customer) {
  return { json: { transactionStatus: "ROLLED_BACK", isCommitted: false, success: false, reason: "CUSTOMER_NOT_FOUND" } };
}

const newBalance = customer.balance + order.totalAmount;

// Enforce constraint: balance cannot exceed credit limit
if (newBalance > customer.creditLimit) {
  // Rollback transaction: delete orphaned order header and child items
  staticData.orders = staticData.orders.filter(o => o.orderId !== order.orderId);
  staticData.orderItems = staticData.orderItems.filter(i => i.orderId !== order.orderId);
  return {
    json: {
      transactionStatus: "ROLLED_BACK",
      isCommitted: false,
      reason: "CREDIT_LIMIT_EXCEEDED",
      currentBalance: customer.balance,
      creditLimit: customer.creditLimit,
      attemptedCharge: order.totalAmount
    }
  };
}

// Commit transaction
customer.balance = newBalance;
const committedOrder = staticData.orders.find(o => o.orderId === order.orderId);
if (committedOrder) committedOrder.status = "COMMITTED";

return {
  json: {
    transactionStatus: "COMMITTED",
    isCommitted: true,
    orderId: order.orderId,
    customerId: customer.customerId,
    updatedBalance: newBalance,
    committedAt: new Date().toISOString()
  }
};

return {
  json: {
    status: "TRANSACTION_ABORTED_SAFELY",
    auditEvent: "ROLLBACK_TRIGGERED",
    details: $input.item.json,
    abortedAt: new Date().toISOString()
  }
};

const staticData = $getWorkflowStaticData('global');
const orderId = $json.orderId;
const order = (staticData.orders || []).find(o => o.orderId === orderId);
const customer = (staticData.customers || []).find(c => c.customerId === order?.customerId);
const items = (staticData.orderItems || []).filter(i => i.orderId === orderId);

return {
  json: {
    orderId: order ? order.orderId : orderId,
    status: order ? order.status : "COMMITTED",
    customer: {
      id: customer ? customer.customerId : "CUST-101",
      name: customer ? customer.name : "Apex Global",
      balance: customer ? customer.balance : 6275.00
    },
    orderDate: order ? order.orderDate : new Date().toISOString(),
    totalAmount: order ? order.totalAmount : 1275.00,
    lineItems: items
  }
};

const item = $input.item.json;
return {
  json: {
    auditStatus: "DATABASE_TRANSACTION_VERIFIED",
    auditEvent: "ACID_TRANSACTION_COMMITTED",
    orderId: item.orderId,
    persistedTotal: item.totalAmount,
    lineItemCount: Array.isArray(item.lineItems) ? item.lineItems.length : 0,
    customerBalance: item.customer ? item.customer.balance : null,
    auditTimestamp: new Date().toISOString()
  }
};
